// src/components/PartnerSection.js
import React from 'react';

const PartnerSection = () => {
    const partners = [
        {
            name: "IME Remit",
            img: "assets/Ime.png",
            color: "linear-gradient(135deg, #4CAF50, #2E7D32)",
            desc: "A pioneer in the remittance industry, providing a secure gateway for your family instantly."
        },
        {
            name: "City Express",
            img: "assets/cityr.jpg",
            color: "linear-gradient(135deg, #1E88E5, #1565C0)",
            desc: "Ensuring your smile with every transaction through wide-reaching networks."
        },
        {
            name: "Prabhu Money",
            img: "assets/prabhur.png",
            color: "linear-gradient(135deg, #00ACC1, #00838F)",
            desc: "Connecting Nepalese globally with a seamless and trusted remittance experience."
        }
    ];

    return (
        <section className="partner-section">
            <h2>Our Remittance Partners</h2>
            <p className="partner-desc">Secure, fast, and reliable money transfer services.</p>
            <div className="partner-grid">
                {partners.map((partner, index) => (
                    <div className="partner-card" style={{ background: partner.color }} key={index}>
                        <h3>
                            <img src={partner.img} width="35" alt={partner.name} style={{ marginRight: '10px', borderRadius: '4px' }} />
                            {partner.name}
                        </h3>
                        <p>{partner.desc}</p>
                    </div>
                ))}
            </div>
        </section>
    );
};

export default PartnerSection;
